def recopier_les_reperes(apps, schema_editor):
    """Les fusions déjà écrites n'ont pas leurs repères recopiés.

    Tant que les deux fiches sont là, personne ne s'en aperçoit : la
    résolution passe par `Patient`. Le jour où l'une est supprimée, le code
    imprimé ne mènerait plus nulle part. On les remplit donc tout de suite,
    depuis les fiches tant qu'elles existent.
    """
    FusionPatient = apps.get_model('patients', 'FusionPatient')
    a_ecrire = []
    for fusion in FusionPatient.objects.select_related('gardee', 'absorbee'):
        if fusion.absorbee is not None:
            fusion.code_absorbee = fusion.absorbee.code_patient
            fusion.ancien_identifiant_absorbee = (
                fusion.absorbee.ancien_identifiant or '')
        else:
            # Une fusion sans fiche absorbée n'existe pas encore à cette
            # date ; au cas où, la copie du journal la porte.
            fusion.code_absorbee = (fusion.copie or {}).get('code_patient', '')
            fusion.ancien_identifiant_absorbee = (
                (fusion.copie or {}).get('ancien_identifiant') or '')
        if fusion.gardee is not None:
            fusion.code_gardee = fusion.gardee.code_patient
        a_ecrire.append(fusion)
    FusionPatient.objects.bulk_update(
        a_ecrire, ['code_absorbee', 'ancien_identifiant_absorbee',
                   'code_gardee'])


